SELECT mi1.info, n.name, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, leaf_71
WHERE ci.movie_id = t.id AND ci.movie_id = mi1.movie_id AND it2.id = leaf_71.pi_info_type_id AND leaf_71.pi_person_id = n.id AND ci.role_id = rt.id AND (kt.kind IN ('tv movie','video game','video movie')) AND kt.id = t.kind_id AND it1.id = mi1.info_type_id AND (n.name ILIKE '%geo%') AND (rt.role IN ('cinematographer','composer','production designer','writer')) AND (it2.id IN ('24')) AND (mi1.info IN ('Austria','East Germany','French','Russian','Soviet Union','Sweden')) AND mi1.movie_id = t.id AND (it1.id IN ('2','4','8')) AND ci.person_id = n.id AND (t.production_year <= 1975) AND (t.production_year >= 1875);